import { useState, useEffect, useCallback } from "react";
import { PageTitle, Card, Btn, Input, Ic, ICONS, Tag, ErrBox, Spinner } from "../components/UI";

/* ═══════════════════════════════════════════════════════════════════════════════
   COMPLETE DASHBOARD — Nyaya-Setu Legal Management System
   Covers: Auth, Cases, Tasks, Hearings, Calendar Events, Invoices, CNR Lookup,
           Document Generator, Quick Stats, Delete Operations, Full CRUD
   ═══════════════════════════════════════════════════════════════════════════════ */

const API_BASE = "http://localhost:8001";

export default function Dashboard({ t, toast }) {
  // ── Auth State ──────────────────────────────────────────────────────────────
  const [token, setToken] = useState(localStorage.getItem("ns_token"));
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [isRegister, setIsRegister] = useState(false);
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");

  // ── Data State ────────────────────────────────────────────────────────────────
  const [cases, setCases] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [hearings, setHearings] = useState([]);
  const [invoices, setInvoices] = useState([]);
  const [calendarEvents, setCalendarEvents] = useState([]);
  const [calendarStats, setCalendarStats] = useState(null);
  const [cnrResult, setCnrResult] = useState(null);
  const [docResult, setDocResult] = useState(null);

  // ── Loading States (per-section) ──────────────────────────────────────────────
  const [loading, setLoading] = useState({
    cases: false, tasks: false, hearings: false, invoices: false,
    calendar: false, cnr: false, doc: false, deleteCase: null,
  });

  // ── Form State ────────────────────────────────────────────────────────────────
  const [newCase, setNewCase] = useState({ title: "", cnr_number: "", court_name: "", client_name: "", status: "Active" });
  const [newTask, setNewTask] = useState({ title: "", description: "", due_date: "", case_id: "" });
  const [newHearing, setNewHearing] = useState({ purpose: "", hearing_date: "", case_id: "", notes: "" });
  const [newInvoice, setNewInvoice] = useState({ client_name: "", amount: "", due_date: "" });
  const [newCalendarEvent, setNewCalendarEvent] = useState({
    title: "", event_type: "hearing", event_date: "", event_time: "", court: "", description: "", matter_id: "",
  });
  const [cnrNumber, setCnrNumber] = useState("");
  const [docGen, setDocGen] = useState({ doc_type: "Rent Agreement", party_a: "", party_b: "", details: "" });

  // ── UI State ──────────────────────────────────────────────────────────────────
  const [activeTab, setActiveTab] = useState("overview");
  const [selectedCase, setSelectedCase] = useState(null);
  const [showCaseDetail, setShowCaseDetail] = useState(false);

  useEffect(() => { if (token) fetchUser(); }, [token]);

  const fetchUser = useCallback(async () => {
    try {
      const res = await fetch(`${API_BASE}/api/auth/me`, { headers: { Authorization: `Bearer ${token}` } });
      if (res.ok) { setUser(await res.json()); fetchAllData(); }
      else handleLogout();
    } catch (e) { toast("Connection error — backend may be offline", "error"); }
  }, [token]);

  const handleLogout = () => {
    localStorage.removeItem("ns_token"); setToken(null); setUser(null);
    setCases([]); setTasks([]); setHearings([]); setInvoices([]); setCalendarEvents([]); setCalendarStats(null);
    toast("Logged out", "info");
  };

  const fetchAllData = useCallback(async () => {
    const headers = { Authorization: `Bearer ${token}` };
    try {
      const [cRes, tRes, hRes, iRes, calRes, calStatsRes] = await Promise.all([
        fetch(`${API_BASE}/api/cases`, { headers }), fetch(`${API_BASE}/api/tasks`, { headers }),
        fetch(`${API_BASE}/api/hearings`, { headers }), fetch(`${API_BASE}/api/invoices`, { headers }),
        fetch(`${API_BASE}/api/calendar/events`, { headers }), fetch(`${API_BASE}/api/calendar/stats/summary`, { headers }),
      ]);
      if (cRes.ok) setCases(await cRes.json()); if (tRes.ok) setTasks(await tRes.json());
      if (hRes.ok) setHearings(await hRes.json()); if (iRes.ok) setInvoices(await iRes.json());
      if (calRes.ok) setCalendarEvents(await calRes.json()); if (calStatsRes.ok) setCalendarStats(await calStatsRes.json());
    } catch (e) { console.error("[Dashboard] fetchAllData error:", e); toast("Failed to load dashboard data", "error"); }
  }, [token]);

  const handleAuth = async () => {
    if (!email || !password) { toast("Email and password are required", "error"); return; }
    if (isRegister && !fullName) { toast("Full name is required", "error"); return; }
    setAuthLoading(true);
    const url = isRegister ? `${API_BASE}/api/auth/register` : `${API_BASE}/api/auth/login`;
    const body = isRegister ? JSON.stringify({ email, password, full_name: fullName || email.split("@")[0], phone: phone || "0000000000" }) : JSON.stringify({ email, password });
    try {
      const res = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body });
      const data = await res.json();
      if (res.ok) {
        if (isRegister) { toast("Registration successful — please log in", "success"); setIsRegister(false); setFullName(""); setPhone(""); }
        else { localStorage.setItem("ns_token", data.access_token); setToken(data.access_token); toast(`Welcome back, ${data.user?.full_name || ""}`, "success"); }
      } else toast(data.detail || "Authentication failed", "error");
    } catch (e) { toast("Server connection failed", "error"); }
    setAuthLoading(false);
  };

  const handleCreateCase = async () => {
    if (!newCase.title.trim()) { toast("Case title is required", "error"); return; }
    setLoading(p => ({ ...p, cases: true }));
    try {
      const res = await fetch(`${API_BASE}/api/cases`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(newCase),
      });
      if (res.ok) { const created = await res.json(); toast(`Case "${created.title}" created`, "success"); setNewCase({ title: "", cnr_number: "", court_name: "", client_name: "", status: "Active" }); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Failed to create case", "error"); }
    } catch (e) { toast("Error creating case", "error"); }
    setLoading(p => ({ ...p, cases: false }));
  };

  const handleDeleteCase = async (caseId) => {
    if (!window.confirm("Delete this case and all associated tasks/hearings?")) return;
    setLoading(p => ({ ...p, deleteCase: caseId }));
    try {
      const res = await fetch(`${API_BASE}/api/cases/${caseId}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });
      if (res.ok) { toast("Case deleted successfully", "success"); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Failed to delete case", "error"); }
    } catch (e) { toast("Error deleting case", "error"); }
    setLoading(p => ({ ...p, deleteCase: null }));
  };

  const fetchCaseDetail = async (caseId) => {
    try {
      const res = await fetch(`${API_BASE}/api/cases/${caseId}`, { headers: { Authorization: `Bearer ${token}` } });
      if (res.ok) { setSelectedCase(await res.json()); setShowCaseDetail(true); }
    } catch (e) { toast("Failed to load case details", "error"); }
  };

  const handleCreateTask = async () => {
    if (!newTask.title.trim() || !newTask.due_date) { toast("Title and Due Date are required", "error"); return; }
    setLoading(p => ({ ...p, tasks: true }));
    try {
      const res = await fetch(`${API_BASE}/api/tasks`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ ...newTask, due_date: new Date(newTask.due_date).toISOString() }),
      });
      if (res.ok) { toast("Task created", "success"); setNewTask({ title: "", description: "", due_date: "", case_id: "" }); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Failed to create task", "error"); }
    } catch (e) { toast("Error creating task", "error"); }
    setLoading(p => ({ ...p, tasks: false }));
  };

  const handleCreateHearing = async () => {
    if (!newHearing.purpose.trim() || !newHearing.hearing_date || !newHearing.case_id) { toast("Purpose, Date, and Case are required", "error"); return; }
    setLoading(p => ({ ...p, hearings: true }));
    try {
      const res = await fetch(`${API_BASE}/api/hearings`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ ...newHearing, hearing_date: new Date(newHearing.hearing_date).toISOString() }),
      });
      if (res.ok) { toast("Hearing scheduled", "success"); setNewHearing({ purpose: "", hearing_date: "", case_id: "", notes: "" }); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Not authorized for this case", "error"); }
    } catch (e) { toast("Error scheduling hearing", "error"); }
    setLoading(p => ({ ...p, hearings: false }));
  };

  const handleCreateInvoice = async () => {
    if (!newInvoice.client_name.trim() || !newInvoice.amount || !newInvoice.due_date) { toast("Client name, amount, and due date are required", "error"); return; }
    setLoading(p => ({ ...p, invoices: true }));
    try {
      const res = await fetch(`${API_BASE}/api/invoices`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({ ...newInvoice, amount: parseFloat(newInvoice.amount), due_date: new Date(newInvoice.due_date).toISOString() }),
      });
      if (res.ok) { toast("Invoice created", "success"); setNewInvoice({ client_name: "", amount: "", due_date: "" }); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Failed to create invoice", "error"); }
    } catch (e) { toast("Error creating invoice", "error"); }
    setLoading(p => ({ ...p, invoices: false }));
  };

  const handleCreateCalendarEvent = async () => {
    if (!newCalendarEvent.title.trim() || !newCalendarEvent.event_date) { toast("Title and event date are required", "error"); return; }
    setLoading(p => ({ ...p, calendar: true }));
    try {
      const res = await fetch(`${API_BASE}/api/calendar/events`, {
        method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(newCalendarEvent),
      });
      if (res.ok) { toast("Calendar event added", "success"); setNewCalendarEvent({ title: "", event_type: "hearing", event_date: "", event_time: "", court: "", description: "", matter_id: "" }); fetchAllData(); }
      else { const err = await res.json(); toast(err.detail || "Failed to add event", "error"); }
    } catch (e) { toast("Error adding calendar event", "error"); }
    setLoading(p => ({ ...p, calendar: false }));
  };

  const handleDeleteCalendarEvent = async (eventId) => {
    if (!window.confirm("Delete this calendar event?")) return;
    try {
      const res = await fetch(`${API_BASE}/api/calendar/events/${eventId}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });
      if (res.ok) { toast("Event deleted", "success"); fetchAllData(); }
    } catch (e) { toast("Error deleting event", "error"); }
  };

  const handleCnrLookup = async () => {
    if (!cnrNumber.trim() || cnrNumber.length < 16) { toast("Enter a valid 16-character CNR number", "error"); return; }
    setLoading(p => ({ ...p, cnr: true })); setCnrResult(null);
    try {
      const res = await fetch(`${API_BASE}/api/cnr/${encodeURIComponent(cnrNumber.trim())}`);
      if (res.ok) { setCnrResult(await res.json()); toast("CNR data fetched", "success"); }
      else { const err = await res.json(); toast(err.detail || "Invalid CNR number", "error"); }
    } catch (e) { toast("CNR lookup failed", "error"); }
    setLoading(p => ({ ...p, cnr: false }));
  };

  const handleGenerateDoc = async () => {
    if (!docGen.party_a.trim() || !docGen.party_b.trim() || !docGen.details.trim()) { toast("All document fields are required", "error"); return; }
    setLoading(p => ({ ...p, doc: true })); setDocResult(null);
    try {
      const res = await fetch(`${API_BASE}/api/generate_doc`, { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` }, body: JSON.stringify(docGen) });
      if (res.ok) { setDocResult(await res.json()); toast("Document generated", "success"); }
      else { const err = await res.json(); toast(err.detail || "Document generation failed", "error"); }
    } catch (e) { toast("Error generating document", "error"); }
    setLoading(p => ({ ...p, doc: false }));
  };

  const formatDate = (d) => { if (!d) return "—"; try { return new Date(d).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }); } catch { return String(d); } };
  const formatDateTime = (d, tm) => { if (!d) return "—"; const ds = formatDate(d); return tm ? `${ds} at ${tm}` : ds; };
  const getStatusColor = (status) => { const s = (status || "").toLowerCase(); if (s.includes("active") || s.includes("open")) return t.green; if (s.includes("pending") || s.includes("wait")) return t.amber; if (s.includes("disposed") || s.includes("closed") || s.includes("resolved")) return t.blue; if (s.includes("overdue") || s.includes("urgent")) return t.red; return t.sub; };
  const getEventTypeIcon = (type) => { const map = { hearing: ICONS.calendar, deadline: ICONS.clock, meeting: ICONS.users, reminder: ICONS.bell }; return map[type] || ICONS.calendar; };
  const pendingTasks = tasks.filter(t => !t.is_completed);
  const upcomingHearings = hearings.filter(h => new Date(h.hearing_date) >= new Date()).sort((a, b) => new Date(a.hearing_date) - new Date(b.hearing_date));
  const totalRevenue = invoices.reduce((sum, i) => sum + (i.amount || 0), 0);
  const pendingRevenue = invoices.filter(i => i.status === "Pending").reduce((sum, i) => sum + (i.amount || 0), 0);

  // ═══════════════════════════════════════════════════════════════════════════════
  // RENDER: AUTH SCREEN
  // ═══════════════════════════════════════════════════════════════════════════════

  if (!token || !user) {
    return (
      <div style={{ maxWidth: 420, margin: "80px auto", padding: "0 20px" }}>
        <Card t={t}>
          <div style={{ textAlign: "center", marginBottom: 28 }}>
            <div style={{ width: 56, height: 56, background: `${t.blue}18`, borderRadius: 14, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 18px" }}>
              <Ic d={ICONS.grid} size={28} color={t.blue} />
            </div>
            <h2 style={{ fontSize: 24, fontWeight: 800, margin: "0 0 6px" }}>{isRegister ? "Create Account" : "Lawyer Login"}</h2>
            <p style={{ fontSize: 14, color: t.sub, margin: 0 }}>{isRegister ? "Join Nyaya-Setu Legal Platform" : "Access your firm dashboard"}</p>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            <Input value={email} onChange={e => setEmail(e.target.value)} placeholder="Email address" type="email" t={t} />
            <Input value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" type="password" t={t} />
            {isRegister && (
              <>
                <Input value={fullName} onChange={e => setFullName(e.target.value)} placeholder="Full Name" t={t} />
                <Input value={phone} onChange={e => setPhone(e.target.value)} placeholder="Phone (Optional)" t={t} />
              </>
            )}
            <Btn onClick={handleAuth} loading={authLoading} t={t} style={{ width: "100%", justifyContent: "center", marginTop: 4 }}>
              {isRegister ? "Create Account" : "Sign In"}
            </Btn>
            <button onClick={() => { setIsRegister(!isRegister); setFullName(""); setPhone(""); }} style={{ background: "none", border: "none", color: t.blue, cursor: "pointer", fontSize: 13, marginTop: 8, textAlign: "center" }}>
              {isRegister ? "Already have an account? Sign in" : "Need an account? Register"}
            </button>
          </div>
        </Card>
      </div>
    );
  }

  // ═══════════════════════════════════════════════════════════════════════════════
  // RENDER: DASHBOARD (Authenticated)
  // ═══════════════════════════════════════════════════════════════════════════════

  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "24px 20px 60px" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 24, flexWrap: "wrap", gap: 12 }}>
        <PageTitle icon="grid" title={`Welcome back, ${user.full_name || user.email}`} desc="Manage your cases, hearings, tasks, billing & calendar in one place." badge={user.role?.toUpperCase() || "LAWYER"} t={t} />
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          <Tag label={`${cases.length} Cases`} variant="info" t={t} style={{ fontSize: 12 }} />
          <button onClick={handleLogout} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 8, padding: "8px 16px", color: t.red, fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Logout</button>
        </div>
      </div>

      {/* Tab Navigation */}
      <div style={{ display: "flex", gap: 8, marginBottom: 28, borderBottom: `2px solid ${t.border}`, paddingBottom: 2, overflowX: "auto" }}>
        {[
          { id: "overview", label: "Overview", icon: ICONS.grid },
          { id: "cases", label: "Cases", icon: ICONS.file },
          { id: "tasks", label: "Tasks", icon: ICONS.check },
          { id: "hearings", label: "Hearings", icon: ICONS.calendar },
          { id: "invoices", label: "Billing", icon: ICONS.dollar },
          { id: "calendar", label: "Calendar", icon: ICONS.calendar },
          { id: "tools", label: "Tools", icon: ICONS.tool },
        ].map(tab => (
          <button key={tab.id} onClick={() => { setActiveTab(tab.id); setShowCaseDetail(false); }} style={{ background: "none", border: "none", borderBottom: `2px solid ${activeTab === tab.id ? t.blue : "transparent"}`, color: activeTab === tab.id ? t.blue : t.sub, padding: "10px 18px", fontSize: 14, fontWeight: activeTab === tab.id ? 700 : 500, cursor: "pointer", display: "flex", alignItems: "center", gap: 8, fontFamily: "inherit", whiteSpace: "nowrap", marginBottom: -2 }}>
            <Ic d={tab.icon} size={16} color={activeTab === tab.id ? t.blue : t.sub} />{tab.label}
          </button>
        ))}
      </div>

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: OVERVIEW
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "overview" && (
        <>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 16, marginBottom: 28 }}>
            <Card t={t} style={{ padding: "20px 24px" }}>
              <div style={{ fontSize: 12, color: t.sub, fontWeight: 600, marginBottom: 8 }}>ACTIVE CASES</div>
              <div style={{ fontSize: 36, fontWeight: 800, color: t.text }}>{cases.length}</div>
              <div style={{ fontSize: 12, color: t.green, marginTop: 4 }}>{cases.filter(c => (c.status || "").toLowerCase() === "active").length} active</div>
            </Card>
            <Card t={t} style={{ padding: "20px 24px" }}>
              <div style={{ fontSize: 12, color: t.sub, fontWeight: 600, marginBottom: 8 }}>UPCOMING HEARINGS</div>
              <div style={{ fontSize: 36, fontWeight: 800, color: t.text }}>{upcomingHearings.length}</div>
              <div style={{ fontSize: 12, color: t.amber, marginTop: 4 }}>Next: {upcomingHearings[0] ? formatDate(upcomingHearings[0].hearing_date) : "None"}</div>
            </Card>
            <Card t={t} style={{ padding: "20px 24px" }}>
              <div style={{ fontSize: 12, color: t.sub, fontWeight: 600, marginBottom: 8 }}>PENDING TASKS</div>
              <div style={{ fontSize: 36, fontWeight: 800, color: t.text }}>{pendingTasks.length}</div>
              <div style={{ fontSize: 12, color: pendingTasks.length > 0 ? t.red : t.green, marginTop: 4 }}>{pendingTasks.length > 0 ? `${pendingTasks.length} need attention` : "All caught up"}</div>
            </Card>
            <Card t={t} style={{ padding: "20px 24px" }}>
              <div style={{ fontSize: 12, color: t.sub, fontWeight: 600, marginBottom: 8 }}>TOTAL BILLED</div>
              <div style={{ fontSize: 36, fontWeight: 800, color: t.text }}>₹{totalRevenue.toLocaleString("en-IN")}</div>
              <div style={{ fontSize: 12, color: t.blue, marginTop: 4 }}>₹{pendingRevenue.toLocaleString("en-IN")} pending</div>
            </Card>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))", gap: 20, marginBottom: 28 }}>
            <Card t={t} style={{ padding: 20 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                <h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>Recent Cases</h3>
                <button onClick={() => setActiveTab("cases")} style={{ background: "none", border: "none", color: t.blue, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>View All →</button>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {cases.slice(0, 5).map(c => (
                  <div key={c.id} onClick={() => fetchCaseDetail(c.id)} style={{ padding: "10px 14px", background: t.surfaceUp, borderRadius: 8, border: `1px solid ${t.border}`, cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <div><div style={{ fontWeight: 600, fontSize: 13 }}>{c.title}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 2 }}>{c.court_name || "No court"} · {c.client_name || "No client"}</div></div>
                    <Tag label={c.status || "Active"} variant="info" t={t} style={{ fontSize: 10, padding: "2px 8px" }} />
                  </div>
                ))}
                {cases.length === 0 && <div style={{ color: t.sub, fontSize: 13, textAlign: "center", padding: 20 }}>No cases yet. Create one in the Cases tab.</div>}
              </div>
            </Card>
            <Card t={t} style={{ padding: 20 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                <h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>Upcoming Hearings</h3>
                <button onClick={() => setActiveTab("hearings")} style={{ background: "none", border: "none", color: t.blue, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>View All →</button>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {upcomingHearings.slice(0, 5).map(h => {
                  const caseObj = cases.find(c => c.id === h.case_id);
                  return <div key={h.id} style={{ padding: "10px 14px", background: t.surfaceUp, borderRadius: 8, border: `1px solid ${t.border}` }}><div style={{ fontWeight: 600, fontSize: 13 }}>{h.purpose}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 2 }}>{formatDate(h.hearing_date)} · {caseObj?.title || `Case #${h.case_id}`}</div></div>;
                })}
                {upcomingHearings.length === 0 && <div style={{ color: t.sub, fontSize: 13, textAlign: "center", padding: 20 }}>No upcoming hearings scheduled.</div>}
              </div>
            </Card>
            <Card t={t} style={{ padding: 20 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
                <h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>Pending Tasks</h3>
                <button onClick={() => setActiveTab("tasks")} style={{ background: "none", border: "none", color: t.blue, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>View All →</button>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                {pendingTasks.slice(0, 5).map(task => {
                  const caseObj = cases.find(c => c.id === task.case_id);
                  const isOverdue = new Date(task.due_date) < new Date();
                  return <div key={task.id} style={{ padding: "10px 14px", background: t.surfaceUp, borderRadius: 8, border: `1px solid ${isOverdue ? t.red : t.border}` }}><div style={{ fontWeight: 600, fontSize: 13 }}>{task.title}</div><div style={{ fontSize: 11, color: isOverdue ? t.red : t.sub, marginTop: 2 }}>Due {formatDate(task.due_date)}{caseObj ? ` · ${caseObj.title}` : ""}{isOverdue && " · OVERDUE"}</div></div>;
                })}
                {pendingTasks.length === 0 && <div style={{ color: t.sub, fontSize: 13, textAlign: "center", padding: 20 }}>No pending tasks. All caught up!</div>}
              </div>
            </Card>
          </div>

          <Card t={t} style={{ padding: 20, marginBottom: 28 }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
              <h3 style={{ fontSize: 15, fontWeight: 700, margin: 0 }}>Calendar Overview</h3>
              <button onClick={() => setActiveTab("calendar")} style={{ background: "none", border: "none", color: t.blue, fontSize: 12, cursor: "pointer", fontWeight: 600 }}>View Calendar →</button>
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 16 }}>
              <div style={{ textAlign: "center", padding: 16, background: t.surfaceUp, borderRadius: 10 }}><div style={{ fontSize: 28, fontWeight: 800, color: t.blue }}>{calendarStats?.total_events || 0}</div><div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>Total Events</div></div>
              <div style={{ textAlign: "center", padding: 16, background: t.surfaceUp, borderRadius: 10 }}><div style={{ fontSize: 28, fontWeight: 800, color: t.green }}>{calendarStats?.upcoming_events || 0}</div><div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>Upcoming</div></div>
              <div style={{ textAlign: "center", padding: 16, background: t.surfaceUp, borderRadius: 10 }}><div style={{ fontSize: 28, fontWeight: 800, color: t.amber }}>{calendarStats?.this_week || 0}</div><div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>This Week</div></div>
              <div style={{ textAlign: "center", padding: 16, background: t.surfaceUp, borderRadius: 10 }}><div style={{ fontSize: 28, fontWeight: 800, color: t.purple || t.blue }}>{calendarEvents.filter(e => e.event_type === "hearing").length}</div><div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>Hearings</div></div>
            </div>
          </Card>
        </>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: CASES
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "cases" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 360px", gap: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0 }}>My Cases</h2>
              <div style={{ fontSize: 13, color: t.sub }}>{cases.length} case{cases.length !== 1 ? "s" : ""} total</div>
            </div>
            {showCaseDetail && selectedCase ? (
              <Card t={t} style={{ padding: 24, marginBottom: 20 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
                  <div>
                    <h2 style={{ fontSize: 22, fontWeight: 800, margin: "0 0 8px" }}>{selectedCase.title}</h2>
                    <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
                      {selectedCase.cnr_number && <Tag label={`CNR: ${selectedCase.cnr_number}`} variant="info" t={t} />}
                      <Tag label={selectedCase.status || "Active"} variant="info" t={t} />
                      {selectedCase.court_name && <span style={{ fontSize: 13, color: t.sub }}>{selectedCase.court_name}</span>}
                    </div>
                  </div>
                  <button onClick={() => setShowCaseDetail(false)} style={{ background: "none", border: "none", color: t.sub, cursor: "pointer", fontSize: 20 }}>×</button>
                </div>
                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 20 }}>
                  <div style={{ padding: 14, background: t.surfaceUp, borderRadius: 8 }}><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Client</div><div style={{ fontSize: 15, fontWeight: 600, marginTop: 4 }}>{selectedCase.client_name || "—"}</div></div>
                  <div style={{ padding: 14, background: t.surfaceUp, borderRadius: 8 }}><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Created</div><div style={{ fontSize: 15, fontWeight: 600, marginTop: 4 }}>{formatDate(selectedCase.created_at)}</div></div>
                </div>
                <div style={{ marginBottom: 16 }}>
                  <h4 style={{ fontSize: 14, fontWeight: 700, margin: "0 0 10px" }}>Linked Tasks</h4>
                  {tasks.filter(t2 => t2.case_id === selectedCase.id).length === 0 ? <div style={{ color: t.sub, fontSize: 13 }}>No tasks linked.</div> : <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>{tasks.filter(t2 => t2.case_id === selectedCase.id).map(t2 => <div key={t2.id} style={{ padding: "8px 12px", background: t.surfaceUp, borderRadius: 6, fontSize: 13, display: "flex", justifyContent: "space-between" }}><span>{t2.title}</span><span style={{ color: t.sub, fontSize: 11 }}>{t2.is_completed ? "Done" : `Due ${formatDate(t2.due_date)}`}</span></div>)}</div>}
                </div>
                <div>
                  <h4 style={{ fontSize: 14, fontWeight: 700, margin: "0 0 10px" }}>Linked Hearings</h4>
                  {hearings.filter(h => h.case_id === selectedCase.id).length === 0 ? <div style={{ color: t.sub, fontSize: 13 }}>No hearings linked.</div> : <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>{hearings.filter(h => h.case_id === selectedCase.id).map(h => <div key={h.id} style={{ padding: "8px 12px", background: t.surfaceUp, borderRadius: 6, fontSize: 13, display: "flex", justifyContent: "space-between" }}><span>{h.purpose}</span><span style={{ color: t.sub, fontSize: 11 }}>{formatDate(h.hearing_date)}</span></div>)}</div>}
                </div>
              </Card>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {cases.length === 0 ? (
                  <div style={{ padding: 50, textAlign: "center", border: `2px dashed ${t.border}`, borderRadius: 12, color: t.sub }}>
                    <Ic d={ICONS.file} size={40} color={t.border} style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 600 }}>No cases yet</div><div style={{ fontSize: 13, marginTop: 4 }}>Create your first case from the sidebar.</div>
                  </div>
                ) : cases.map(c => (
                  <Card key={c.id} t={t} style={{ padding: "16px 20px", display: "flex", alignItems: "center", justifyContent: "space-between", cursor: "pointer" }} hover>
                    <div style={{ flex: 1 }} onClick={() => fetchCaseDetail(c.id)}>
                      <h4 style={{ margin: "0 0 6px", fontSize: 15, fontWeight: 700 }}>{c.title}</h4>
                      <div style={{ fontSize: 12, color: t.sub, display: "flex", gap: 14, flexWrap: "wrap" }}>
                        {c.cnr_number && <span>CNR: {c.cnr_number}</span>}{c.court_name && <span>🏛 {c.court_name}</span>}{c.client_name && <span>👤 {c.client_name}</span>}
                        <span>📋 {tasks.filter(t2 => t2.case_id === c.id).length} tasks</span><span>📅 {hearings.filter(h => h.case_id === c.id).length} hearings</span>
                      </div>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                      <Tag label={c.status || "Active"} variant="info" t={t} style={{ background: `${getStatusColor(c.status)}22`, color: getStatusColor(c.status), border: `1px solid ${getStatusColor(c.status)}44` }} />
                      <button onClick={e => { e.stopPropagation(); handleDeleteCase(c.id); }} disabled={loading.deleteCase === c.id} style={{ background: "none", border: "none", color: t.red, cursor: "pointer", fontSize: 18, padding: "4px 8px", opacity: loading.deleteCase === c.id ? 0.5 : 1 }} title="Delete case">{loading.deleteCase === c.id ? <Spinner size={14} /> : "🗑"}</button>
                    </div>
                  </Card>
                ))}
              </div>
            )}
          </div>
          <div>
            <Card t={t} style={{ padding: 20, position: "sticky", top: 24 }}>
              <h3 style={{ fontSize: 16, fontWeight: 800, margin: "0 0 18px" }}>Add New Case</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <Input value={newCase.title} onChange={e => setNewCase({ ...newCase, title: e.target.value })} placeholder="Case Title *" t={t} />
                <Input value={newCase.cnr_number} onChange={e => setNewCase({ ...newCase, cnr_number: e.target.value })} placeholder="CNR Number (Optional)" t={t} />
                <Input value={newCase.court_name} onChange={e => setNewCase({ ...newCase, court_name: e.target.value })} placeholder="Court Name" t={t} />
                <Input value={newCase.client_name} onChange={e => setNewCase({ ...newCase, client_name: e.target.value })} placeholder="Client Name" t={t} />
                <select value={newCase.status} onChange={e => setNewCase({ ...newCase, status: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }}>
                  <option value="Active">Active</option><option value="Pending">Pending</option><option value="Disposed">Disposed</option><option value="Closed">Closed</option>
                </select>
                <Btn onClick={handleCreateCase} loading={loading.cases} t={t} style={{ width: "100%", justifyContent: "center" }}>Create Case</Btn>
              </div>
            </Card>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: TASKS
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "tasks" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 360px", gap: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0 }}>Tasks</h2>
              <div style={{ display: "flex", gap: 8 }}>
                <Tag label={`${pendingTasks.length} Pending`} variant="warning" t={t} />
                <Tag label={`${tasks.filter(t2 => t2.is_completed).length} Done`} variant="success" t={t} />
              </div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {tasks.length === 0 ? (
                <div style={{ padding: 50, textAlign: "center", border: `2px dashed ${t.border}`, borderRadius: 12, color: t.sub }}>
                  <Ic d={ICONS.check} size={40} color={t.border} style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 600 }}>No tasks yet</div>
                </div>
              ) : tasks.map(task => {
                const caseObj = cases.find(c => c.id === task.case_id);
                const isOverdue = !task.is_completed && new Date(task.due_date) < new Date();
                return (
                  <Card key={task.id} t={t} style={{ padding: "14px 18px", display: "flex", alignItems: "flex-start", gap: 14, borderLeft: `4px solid ${task.is_completed ? t.green : isOverdue ? t.red : t.amber}` }}>
                    <div style={{ width: 20, height: 20, borderRadius: 4, border: `2px solid ${task.is_completed ? t.green : t.border}`, background: task.is_completed ? t.green : "transparent", cursor: "pointer", flexShrink: 0, marginTop: 2 }} onClick={() => handleToggleTask(task.id, task.is_completed)} />
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 700, fontSize: 14, textDecoration: task.is_completed ? "line-through" : "none", color: task.is_completed ? t.sub : t.text }}>{task.title}</div>
                      {task.description && <div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>{task.description}</div>}
                      <div style={{ fontSize: 11, color: t.sub, marginTop: 6, display: "flex", gap: 12 }}>
                        <span style={{ color: isOverdue ? t.red : t.sub }}>📅 Due: {formatDate(task.due_date)}{isOverdue && " · OVERDUE"}</span>
                        {caseObj && <span>📁 {caseObj.title}</span>}
                      </div>
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
          <div>
            <Card t={t} style={{ padding: 20, position: "sticky", top: 24 }}>
              <h3 style={{ fontSize: 16, fontWeight: 800, margin: "0 0 18px" }}>Add Task</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <Input value={newTask.title} onChange={e => setNewTask({ ...newTask, title: e.target.value })} placeholder="Task title *" t={t} />
                <Input value={newTask.description} onChange={e => setNewTask({ ...newTask, description: e.target.value })} placeholder="Description (Optional)" t={t} />
                <input type="date" value={newTask.due_date} onChange={e => setNewTask({ ...newTask, due_date: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }} />
                <select value={newTask.case_id} onChange={e => setNewTask({ ...newTask, case_id: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }}>
                  <option value="">Select Case (Optional)</option>{cases.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                </select>
                <Btn onClick={handleCreateTask} loading={loading.tasks} t={t} style={{ width: "100%", justifyContent: "center" }}>Add Task</Btn>
              </div>
            </Card>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: HEARINGS
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "hearings" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 360px", gap: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0 }}>Hearings</h2>
              <div style={{ fontSize: 13, color: t.sub }}>{hearings.length} total · {upcomingHearings.length} upcoming</div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {hearings.length === 0 ? (
                <div style={{ padding: 50, textAlign: "center", border: `2px dashed ${t.border}`, borderRadius: 12, color: t.sub }}>
                  <Ic d={ICONS.calendar} size={40} color={t.border} style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 600 }}>No hearings scheduled</div>
                </div>
              ) : hearings.sort((a, b) => new Date(a.hearing_date) - new Date(b.hearing_date)).map(h => {
                const caseObj = cases.find(c => c.id === h.case_id);
                const isPast = new Date(h.hearing_date) < new Date();
                return (
                  <Card key={h.id} t={t} style={{ padding: "14px 18px", borderLeft: `4px solid ${isPast ? t.sub : t.blue}`, opacity: isPast ? 0.7 : 1 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 15 }}>{h.purpose}</div>
                        <div style={{ fontSize: 12, color: t.sub, marginTop: 6, display: "flex", gap: 14, flexWrap: "wrap" }}>
                          <span>📅 {formatDate(h.hearing_date)}</span>{caseObj && <span>📁 {caseObj.title}</span>}{h.notes && <span>📝 {h.notes}</span>}
                        </div>
                      </div>
                      {isPast && <Tag label="Past" variant="info" t={t} style={{ fontSize: 10 }} />}
                    </div>
                  </Card>
                );
              })}
            </div>
          </div>
          <div>
            <Card t={t} style={{ padding: 20, position: "sticky", top: 24 }}>
              <h3 style={{ fontSize: 16, fontWeight: 800, margin: "0 0 18px" }}>Schedule Hearing</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <Input value={newHearing.purpose} onChange={e => setNewHearing({ ...newHearing, purpose: e.target.value })} placeholder="Purpose (e.g. Bail Hearing) *" t={t} />
                <input type="date" value={newHearing.hearing_date} onChange={e => setNewHearing({ ...newHearing, hearing_date: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }} />
                <select value={newHearing.case_id} onChange={e => setNewHearing({ ...newHearing, case_id: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }}>
                  <option value="">Select Case *</option>{cases.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                </select>
                <Input value={newHearing.notes} onChange={e => setNewHearing({ ...newHearing, notes: e.target.value })} placeholder="Notes (Optional)" t={t} />
                <Btn onClick={handleCreateHearing} loading={loading.hearings} t={t} style={{ width: "100%", justifyContent: "center" }}>Schedule Hearing</Btn>
              </div>
            </Card>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: INVOICES / BILLING
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "invoices" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 360px", gap: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0 }}>Invoices & Billing</h2>
              <div style={{ display: "flex", gap: 8 }}>
                <Tag label={`₹${totalRevenue.toLocaleString("en-IN")} Total`} variant="info" t={t} />
                <Tag label={`₹${pendingRevenue.toLocaleString("en-IN")} Pending`} variant="warning" t={t} />
              </div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {invoices.length === 0 ? (
                <div style={{ padding: 50, textAlign: "center", border: `2px dashed ${t.border}`, borderRadius: 12, color: t.sub }}>
                  <Ic d={ICONS.dollar} size={40} color={t.border} style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 600 }}>No invoices yet</div>
                </div>
              ) : invoices.map(inv => (
                <Card key={inv.id} t={t} style={{ padding: "14px 18px", display: "flex", justifyContent: "space-between", alignItems: "center", borderLeft: `4px solid ${inv.status === "Paid" ? t.green : inv.status === "Overdue" ? t.red : t.amber}` }}>
                  <div>
                    <div style={{ fontWeight: 700, fontSize: 15 }}>{inv.client_name}</div>
                    <div style={{ fontSize: 12, color: t.sub, marginTop: 4 }}>Due {formatDate(inv.due_date)} · Created {formatDate(inv.created_at)}</div>
                  </div>
                  <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                    <div style={{ fontSize: 20, fontWeight: 800, color: t.text }}>₹{inv.amount?.toLocaleString("en-IN") || "0"}</div>
                    <Tag label={inv.status || "Pending"} variant={inv.status === "Paid" ? "success" : inv.status === "Overdue" ? "danger" : "warning"} t={t} />
                  </div>
                </Card>
              ))}
            </div>
          </div>
          <div>
            <Card t={t} style={{ padding: 20, position: "sticky", top: 24 }}>
              <h3 style={{ fontSize: 16, fontWeight: 800, margin: "0 0 18px" }}>New Invoice</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <Input value={newInvoice.client_name} onChange={e => setNewInvoice({ ...newInvoice, client_name: e.target.value })} placeholder="Client Name *" t={t} />
                <Input value={newInvoice.amount} onChange={e => setNewInvoice({ ...newInvoice, amount: e.target.value })} placeholder="Amount (₹) *" type="number" t={t} />
                <input type="date" value={newInvoice.due_date} onChange={e => setNewInvoice({ ...newInvoice, due_date: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }} />
                <Btn onClick={handleCreateInvoice} loading={loading.invoices} t={t} style={{ width: "100%", justifyContent: "center" }}>Create Invoice</Btn>
              </div>
            </Card>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: CALENDAR EVENTS
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "calendar" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 360px", gap: 24 }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 20 }}>
              <h2 style={{ fontSize: 20, fontWeight: 800, margin: 0 }}>Calendar Events</h2>
              <div style={{ display: "flex", gap: 8 }}>
                {calendarStats && <><Tag label={`${calendarStats.total_events} Total`} variant="info" t={t} /><Tag label={`${calendarStats.upcoming_events} Upcoming`} variant="success" t={t} /></>}
              </div>
            </div>
            {calendarStats && (
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 12, marginBottom: 20 }}>
                <div style={{ padding: 14, background: t.surfaceUp, borderRadius: 10, textAlign: "center" }}><div style={{ fontSize: 24, fontWeight: 800, color: t.blue }}>{calendarStats.total_events}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 4 }}>Total Events</div></div>
                <div style={{ padding: 14, background: t.surfaceUp, borderRadius: 10, textAlign: "center" }}><div style={{ fontSize: 24, fontWeight: 800, color: t.green }}>{calendarStats.upcoming_events}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 4 }}>Upcoming</div></div>
                <div style={{ padding: 14, background: t.surfaceUp, borderRadius: 10, textAlign: "center" }}><div style={{ fontSize: 24, fontWeight: 800, color: t.amber }}>{calendarStats.this_week}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 4 }}>This Week</div></div>
                {calendarStats.by_type && Object.entries(calendarStats.by_type).map(([type, count]) => <div key={type} style={{ padding: 14, background: t.surfaceUp, borderRadius: 10, textAlign: "center" }}><div style={{ fontSize: 24, fontWeight: 800, color: t.purple || t.blue }}>{count}</div><div style={{ fontSize: 11, color: t.sub, marginTop: 4, textTransform: "capitalize" }}>{type}s</div></div>)}
              </div>
            )}
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {calendarEvents.length === 0 ? (
                <div style={{ padding: 50, textAlign: "center", border: `2px dashed ${t.border}`, borderRadius: 12, color: t.sub }}>
                  <Ic d={ICONS.calendar} size={40} color={t.border} style={{ marginBottom: 12 }} /><div style={{ fontSize: 16, fontWeight: 600 }}>No calendar events</div>
                </div>
              ) : calendarEvents.map(evt => {
                const caseObj = cases.find(c => c.id === evt.matter_id);
                return (
                  <Card key={evt.id} t={t} style={{ padding: "14px 18px", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                    <div style={{ display: "flex", gap: 14, alignItems: "flex-start" }}>
                      <div style={{ width: 40, height: 40, borderRadius: 10, background: `${t.blue}18`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                        <Ic d={getEventTypeIcon(evt.event_type)} size={20} color={t.blue} />
                      </div>
                      <div>
                        <div style={{ fontWeight: 700, fontSize: 15 }}>{evt.title}</div>
                        <div style={{ fontSize: 12, color: t.sub, marginTop: 4, display: "flex", gap: 14, flexWrap: "wrap" }}>
                          <span>📅 {formatDateTime(evt.event_date, evt.event_time)}</span><span style={{ textTransform: "capitalize" }}>🏷 {evt.event_type}</span>{evt.court && <span>🏛 {evt.court}</span>}{caseObj && <span>📁 {caseObj.title}</span>}
                        </div>
                        {evt.description && <div style={{ fontSize: 12, color: t.sub, marginTop: 6, fontStyle: "italic" }}>{evt.description}</div>}
                      </div>
                    </div>
                    <button onClick={() => handleDeleteCalendarEvent(evt.id)} style={{ background: "none", border: "none", color: t.red, cursor: "pointer", fontSize: 16, padding: "4px" }} title="Delete event">🗑</button>
                  </Card>
                );
              })}
            </div>
          </div>
          <div>
            <Card t={t} style={{ padding: 20, position: "sticky", top: 24 }}>
              <h3 style={{ fontSize: 16, fontWeight: 800, margin: "0 0 18px" }}>Add Calendar Event</h3>
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <Input value={newCalendarEvent.title} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, title: e.target.value })} placeholder="Event Title *" t={t} />
                <select value={newCalendarEvent.event_type} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, event_type: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }}>
                  <option value="hearing">Hearing</option><option value="deadline">Deadline</option><option value="meeting">Meeting</option><option value="reminder">Reminder</option>
                </select>
                <input type="date" value={newCalendarEvent.event_date} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, event_date: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }} />
                <input type="time" value={newCalendarEvent.event_time} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, event_time: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }} />
                <Input value={newCalendarEvent.court} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, court: e.target.value })} placeholder="Court / Venue" t={t} />
                <select value={newCalendarEvent.matter_id} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, matter_id: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14 }}>
                  <option value="">Link to Case (Optional)</option>{cases.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                </select>
                <Input value={newCalendarEvent.description} onChange={e => setNewCalendarEvent({ ...newCalendarEvent, description: e.target.value })} placeholder="Description (Optional)" t={t} />
                <Btn onClick={handleCreateCalendarEvent} loading={loading.calendar} t={t} style={{ width: "100%", justifyContent: "center" }}>Add Event</Btn>
              </div>
            </Card>
          </div>
        </div>
      )}

      {/* ═══════════════════════════════════════════════════════════════════════════
         TAB: TOOLS (CNR Lookup + Document Generator)
         ═══════════════════════════════════════════════════════════════════════════ */}
      {activeTab === "tools" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>
          <Card t={t} style={{ padding: 24 }}>
            <h3 style={{ fontSize: 18, fontWeight: 800, margin: "0 0 18px", display: "flex", alignItems: "center", gap: 10 }}>
              <Ic d={ICONS.search} size={22} color={t.blue} />CNR Number Lookup
            </h3>
            <div style={{ display: "flex", gap: 12, marginBottom: 20, flexWrap: "wrap" }}>
              <Input value={cnrNumber} onChange={e => setCnrNumber(e.target.value.toUpperCase())} placeholder="Enter 16-character CNR number" style={{ flex: 1, minWidth: 250 }} t={t} />
              <Btn onClick={handleCnrLookup} loading={loading.cnr} t={t}>Lookup</Btn>
            </div>
            {cnrResult && (
              <div style={{ padding: 20, background: t.surfaceUp, borderRadius: 12, border: `1px solid ${t.border}` }}>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16 }}>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>CNR Number</div><div style={{ fontSize: 15, fontWeight: 700, marginTop: 4 }}>{cnrResult.cnr_number}</div></div>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Title</div><div style={{ fontSize: 15, fontWeight: 700, marginTop: 4 }}>{cnrResult.title}</div></div>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Court</div><div style={{ fontSize: 15, fontWeight: 600, marginTop: 4 }}>{cnrResult.court_name}</div></div>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Status</div><div style={{ marginTop: 4 }}><Tag label={cnrResult.status} variant="info" t={t} style={{ background: `${getStatusColor(cnrResult.status)}22`, color: getStatusColor(cnrResult.status) }} /></div></div>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Filing Date</div><div style={{ fontSize: 15, fontWeight: 600, marginTop: 4 }}>{formatDate(cnrResult.filing_date)}</div></div>
                  <div><div style={{ fontSize: 11, color: t.sub, textTransform: "uppercase", letterSpacing: 1 }}>Next Hearing</div><div style={{ fontSize: 15, fontWeight: 600, marginTop: 4, color: t.blue }}>{formatDate(cnrResult.next_hearing)}</div></div>
                </div>
              </div>
            )}
          </Card>

          <Card t={t} style={{ padding: 24 }}>
            <h3 style={{ fontSize: 18, fontWeight: 800, margin: "0 0 18px", display: "flex", alignItems: "center", gap: 10 }}>
              <Ic d={ICONS.file} size={22} color={t.blue} />Legal Document Generator
            </h3>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginBottom: 16 }}>
              <div>
                <label style={{ fontSize: 12, color: t.sub, fontWeight: 600, display: "block", marginBottom: 6 }}>Document Type</label>
                <select value={docGen.doc_type} onChange={e => setDocGen({ ...docGen, doc_type: e.target.value })} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "10px 16px", color: t.text, fontFamily: "inherit", fontSize: 14, width: "100%" }}>
                  <option value="Rent Agreement">Rent Agreement</option><option value="Legal Notice">Legal Notice</option>
                </select>
              </div>
              <div>
                <label style={{ fontSize: 12, color: t.sub, fontWeight: 600, display: "block", marginBottom: 6 }}>Party A (Your Client)</label>
                <Input value={docGen.party_a} onChange={e => setDocGen({ ...docGen, party_a: e.target.value })} placeholder="e.g. Rajesh Sharma" t={t} />
              </div>
              <div>
                <label style={{ fontSize: 12, color: t.sub, fontWeight: 600, display: "block", marginBottom: 6 }}>Party B</label>
                <Input value={docGen.party_b} onChange={e => setDocGen({ ...docGen, party_b: e.target.value })} placeholder="e.g. Priya Patel" t={t} />
              </div>
            </div>
            <div style={{ marginBottom: 16 }}>
              <label style={{ fontSize: 12, color: t.sub, fontWeight: 600, display: "block", marginBottom: 6 }}>Details / Subject</label>
              <textarea value={docGen.details} onChange={e => setDocGen({ ...docGen, details: e.target.value })} placeholder="Enter document details, subject matter, or specific clauses..." rows={4} style={{ background: t.surfaceUp, border: `1.5px solid ${t.border}`, borderRadius: 9, padding: "12px 16px", color: t.text, fontFamily: "inherit", fontSize: 14, width: "100%", resize: "vertical" }} />
            </div>
            <Btn onClick={handleGenerateDoc} loading={loading.doc} t={t}>Generate Document</Btn>
            {docResult && (
              <div style={{ marginTop: 20, padding: 20, background: t.surfaceUp, borderRadius: 12, border: `1px solid ${t.border}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
                  <h4 style={{ margin: 0, fontSize: 15 }}>{docResult.doc_type}</h4>
                  <button onClick={() => { navigator.clipboard.writeText(docResult.content); toast("Document copied to clipboard", "success"); }} style={{ background: t.blue, color: "#fff", border: "none", borderRadius: 6, padding: "6px 14px", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}>Copy Text</button>
                </div>
                <pre style={{ whiteSpace: "pre-wrap", fontFamily: "inherit", fontSize: 13, lineHeight: 1.6, color: t.text, margin: 0, maxHeight: 400, overflow: "auto" }}>{docResult.content}</pre>
              </div>
            )}
          </Card>
        </div>
      )}
    </div>
  );
}
